// Version A: each instance stores full state
class ItemA {
  constructor(public id: number, public color: string, public textureData: Uint8Array) {}
}

// Version B: shared intrinsic object via factory, instances keep only extrinsic id
class SharedVisual { constructor(public color: string, public textureData: Uint8Array) {} }
class VisualFactory { private cache = new Map<string, SharedVisual>(); /* returns shared visuals */ }
class ItemB { constructor(public id: number, public visual: SharedVisual) {} }
